// Exact all-reflection common-chart receiver. Reuses frozen long-group corpus and spelling register.
#define main additive_main
#include "lp2_q8_shared_global_strong_anchor.cpp"
#undef main
constexpr int R=37,DIM=35,RC=35;
using RV=array<uint8_t,36>;
struct RS{
 int d=DIM;array<RV,R>a{};
 RS(){a[1][RC]=1;for(int x=2;x<R;x++)a[x][x-2]=1;}
 RV equation(Edge e)const{RV v{};for(int i=0;i<36;i++)v[i]=sub[(a[e.c][i]+a[e.p][i])%N][a[N+e.j][i]];return v;}
 RV difference(int x,int y)const{RV v{};for(int i=0;i<36;i++)v[i]=sub[a[x][i]][a[y][i]];return v;}
 bool impose(const RV&eq){int p=d-1;while(p>=0&&!eq[p])p--;if(p<0)return !eq[RC];int last=d-1,iv=inv[eq[p]];for(auto&r:a){int f=mul[r[p]][iv];if(f){for(int j=0;j<d;j++)if(j!=p)r[j]=sub[r[j]][mul[f][eq[j]]];r[RC]=sub[r[RC]][mul[f][eq[RC]]];}if(p!=last)r[p]=r[last];r[last]=0;}d--;return true;}
 bool valid()const{for(int x=0;x<N;x++)for(int y=0;y<x;y++)if(a[x]==a[y])return false;for(int j=0;j<4;j++)if(a[N+j]!=a[N+j+4])return true;return false;}
 string sig()const{string s(1,char(d));s.append((const char*)a.data(),sizeof(a));return s;}
 string norm(const RV&v)const{int p=0;while(p<d&&!v[p])p++;if(p==d)return v[RC]?"!":"";string s(d+1,'\0');int t=inv[v[p]];for(int i=0;i<d;i++)s[i]=char(mul[t][v[i]]);s[d]=char(mul[t][v[RC]]);return s;}
 void evaluate(const RV&z,Perm&pi,Key&k)const{for(int x=0;x<R;x++){int v=a[x][RC];for(int i=0;i<d;i++)v+=a[x][i]*z[i];if(x<N)pi[x]=v%N;else k[x-N]=v%N;}}
};
struct RF{
 const RS&s;unordered_set<string>neq;array<int8_t,N*N*Q>cache;bool dead=false;
 RF(const RS&v):s(v){cache.fill(-1);unordered_map<string,U>directions;for(int x=0;x<N;x++)for(int y=0;y<x;y++){string z=s.norm(s.difference(x,y));if(z.empty()){dead=true;return;}if(z=="!")continue;if(neq.insert(z).second){int c=uint8_t(z.back());z.pop_back();auto&mask=directions[z];mask|=1u<<c;if(mask==ALL){dead=true;return;}}}}
 bool allowed(Edge e){auto&x=cache[(e.c*N+e.p)*Q+e.j];if(x>=0)return x;string v=s.norm(s.equation(e));return x=(v!="!"&&!neq.count(v));}
 bool allowed(const Option&o){for(auto e:o.e)if(!allowed(e))return false;return true;}
};
bool localReflection(const string&c,const string&w,int start,vector<Edge>*edges=nullptr){array<array<int8_t,N>,Q>m;for(auto&r:m)r.fill(-1);array<int,Q>fixed;fixed.fill(-1);int j=start;for(int i=0;i<(int)c.size();i++){int p=val(w[i]),x=val(c[i]);if(!p){if(x)return false;continue;}if((m[j][p]>=0&&m[j][p]!=x)||(m[j][x]>=0&&m[j][x]!=p))return false;if(p==x){if(fixed[j]>=0&&fixed[j]!=p)return false;fixed[j]=p;}m[j][p]=x;m[j][x]=p;if(edges)edges->push_back({uint8_t(x),uint8_t(p),uint8_t(j)});j=(j+1)&7;}return true;}
vector<Option> rdomain(const string&c,bool anchor){vector<Option>out;for(auto&w:by[c.size()]){if(!localReflection(c,w,0))continue;for(int j=0;j<(anchor?1:Q);j++){Option o{{},w,j};localReflection(c,w,j,&o.e);out.push_back(move(o));}}return out;}
Maps rmaps(const Perm&pi,const Key&k){Perm ip{};for(int i=0;i<N;i++)ip[pi[i]]=i;Maps m{};for(int j=0;j<Q;j++)for(int c=0;c<N;c++)m[j][c]=ip[md(k[j]-pi[c])];return m;}
string rencode(const string&w,const Perm&pi,const Key&k,int j){Perm ip{};for(int i=0;i<N;i++)ip[pi[i]]=i;string c;for(char a:w){int p=val(a);if(!p)c+='0';else{c+=SYM[ip[md(k[j]-pi[p])]];j=(j+1)&7;}}return c;}
bool rEqual(const Perm&a,const Key&k,const Perm&b,const Key&l){auto x=rmaps(a,k),y=rmaps(b,l);for(int r=0;r<Q;r++){bool ok=true;for(int j=0;j<Q;j++)ok&=x[j]==y[(j+r)&7];if(ok)return true;}return false;}
vector<int> rankProfile(){vector<pair<int,int>>v;for(int i=0;i<(int)ORIGINAL.size();i++){int n=0;for(auto&w:by[ORIGINAL[i].size()])n+=localReflection(ORIGINAL[i],w,0);v.emplace_back(n,i);}sort(v.begin(),v.end());vector<int>ids;for(auto[n,i]:v)ids.push_back(i);for(int j=0;j<20;j++)cout<<"PROFILE "<<j<<" "<<v[j].second<<" "<<ORIGINAL[v[j].second]<<" "<<v[j].first<<"\n";return ids;}
struct RStats{uint64_t nodes=0,joins=0,options=0,keys=0,pairs=0;};
struct RSearch{
 vector<string>C;vector<vector<Option>>domains;vector<RS>seeds;vector<int>order,held,excludedR;int first,second,budget;atomic<bool>found{false},timed{false};atomic<int>next{0},done{0};chrono::steady_clock::time_point deadline;mutex lock;Perm answer{};Key answerK{};int answerOOV=-1;
 RSearch(vector<string>c,const vector<int>&ids,int i,int j):C(move(c)),domains(C.size()),first(ids[i]),second(ids[j]),budget(3-(j-1)){
 for(int k=0;k<20;k++){int id=ids[k];if(k<j&&k!=i){excludedR.push_back(id);continue;}domains[id]=rdomain(C[id],id==first);if(id!=first&&id!=second)order.push_back(id);}held.assign(ids.begin()+20,ids.end());sort(order.begin(),order.end(),[&](int x,int y){return log2(max<size_t>(1,domains[x].size()))/C[x].size()<log2(max<size_t>(1,domains[y].size()))/C[y].size();});RS base;unordered_set<string>seen;for(auto&o:domains[first]){RS s;if(extendR(base,o,s)&&seen.insert(s.sig()).second)seeds.push_back(s);}cout<<"ANCHOR "<<first<<" "<<second<<" seeds="<<seeds.size()<<" secondary="<<domains[second].size()<<" budget="<<budget<<endl;}
 bool stop(){if(found||timed)return true;if(chrono::steady_clock::now()>=deadline){timed=true;return true;}return false;}
 static bool extendR(const RS&a,const Option&o,RS&b){b=a;for(auto e:o.e)if(!b.impose(b.equation(e)))return false;return b.valid();}
 void check(const RS&s,const RV&z,RStats&st){st.keys++;Perm pi{};Key k{};s.evaluate(z,pi,k);U seen=0;for(int p:pi){U b=1u<<p;if(seen&b)return;seen|=b;}if(equal(k.begin(),k.begin()+4,k.begin()+4))return;auto m=rmaps(pi,k);if(!support(C[first],m)||!support(C[second],m))return;for(int id:excludedR)if(support(C[id],m))return;int n=0;for(int id:order)if(!support(C[id],m)&&++n>budget)return;lock_guard<mutex>l(lock);if(!found){answer=pi;answerK=k;answerOOV=n+excludedR.size();found=true;}}
 void enumerate(const RS&s,RStats&st){vector<RV>neq;unordered_set<string>seen;for(int x=0;x<N;x++)for(int y=0;y<x;y++){auto v=s.difference(x,y);auto f=s.norm(v);if(f.empty())return;if(f!="!"&&seen.insert(f).second)neq.push_back(v);}RV z{};if(!s.d){check(s,z,st);return;}auto visit=[&](auto&&self,int i)->void{if(stop())return;if(i==s.d-1){U used=0;for(auto&v:neq){int t=v[RC];for(int j=0;j<i;j++)t+=v[j]*z[j];t%=N;if(!v[i]){if(!t)return;}else{used|=1u<<mul[md(-t)][inv[v[i]]];if(used==ALL)return;}}U ok=ALL^used;while(ok){int t=__builtin_ctz(ok);ok&=ok-1;z[i]=t;check(s,z,st);if(stop())return;}return;}for(int t=0;t<N;t++){z[i]=t;self(self,i+1);if(stop())return;}};visit(visit,0);}
 vector<int>live(int id,RF&f,size_t cap,RStats&st){vector<int>v;for(int j=0;j<(int)domains[id].size();j++){st.options++;if(f.allowed(domains[id][j])){v.push_back(j);if(v.size()>=cap)break;}}return v;}
 void dfs(const RS&s,vector<int>rem,int b,RStats&st){if(stop())return;st.nodes++;if(s.d<=3||int(rem.size())<=b){enumerate(s,st);return;}RF f(s);if(f.dead)return;int pick=-1;vector<int>best;size_t cap=SIZE_MAX;int ntry=min<int>(rem.size(),s.d>15?4:8);for(int i=0;i<ntry;){auto v=live(rem[i],f,cap,st);if(v.empty()){if(!b)return;b--;rem.erase(rem.begin()+i);ntry--;if(pick>i)pick--;continue;}if(pick<0||v.size()<cap){pick=i;best=move(v);cap=best.size();}i++;}if(pick<0){enumerate(s,st);return;}int id=rem[pick];rem.erase(rem.begin()+pick);vector<RS>branches;unordered_set<string>seen;for(int j:best){if(stop())return;st.joins++;RS x;if(extendR(s,domains[id][j],x)&&seen.insert(x.sig()).second)branches.push_back(move(x));}stable_sort(branches.begin(),branches.end(),[](const RS&a,const RS&b){return a.d<b.d;});for(auto&x:branches){dfs(x,rem,b,st);if(stop())return;}if(b)dfs(s,rem,b-1,st);}
 void run(int sec,int threads){deadline=chrono::steady_clock::now()+chrono::seconds(sec);vector<RStats>st(threads);vector<thread>pool;for(int t=0;t<threads;t++)pool.emplace_back([&,t]{auto&z=st[t];while(!stop()){int i=next++;if(i>=(int)seeds.size())break;auto&s=seeds[i];RF f(s);if(!f.dead){auto opts=live(second,f,SIZE_MAX,z);vector<RS>branches;unordered_set<string>seen;for(int j:opts){if(stop())break;z.pairs++;RS x;if(extendR(s,domains[second][j],x)&&seen.insert(x.sig()).second)branches.push_back(move(x));}stable_sort(branches.begin(),branches.end(),[](const RS&a,const RS&b){return a.d<b.d;});for(auto&x:branches){dfs(x,order,budget,z);if(stop())break;}}if(!stop()){int n=++done;if(n%10==0){lock_guard<mutex>l(lock);cout<<"DONE "<<n<<"/"<<seeds.size()<<endl;}}}});for(auto&t:pool)t.join();RStats a;for(auto&z:st){a.nodes+=z.nodes;a.joins+=z.joins;a.options+=z.options;a.keys+=z.keys;a.pairs+=z.pairs;}cout<<"RESULT found="<<found<<" timed="<<timed<<" done="<<done<<"/"<<seeds.size()<<" nodes="<<a.nodes<<" joins="<<a.joins<<" keys="<<a.keys<<" options="<<a.options<<" pairs="<<a.pairs<<" OOV="<<answerOOV<<endl;if(found){cout<<"PI";for(int x:answer)cout<<" "<<x;cout<<"\nKEY";for(int x:answerK)cout<<" "<<x;cout<<endl;auto m=rmaps(answer,answerK);int h=0;for(int i:held)h+=support(C[i],m);cout<<"HELD_SUPPORT "<<h<<"/"<<held.size()<<endl;}}
};
int main(int argc,char**argv){if(argc!=7){cerr<<"usage: reflection DICTIONARY SEED SECONDS THREADS FIRST SECOND\n";return 2;}init();dictionary(argv[1]);auto ids=rankProfile();int seed=stoi(argv[2]),sec=stoi(argv[3]),threads=stoi(argv[4]),i=stoi(argv[5]),j=stoi(argv[6]);if(i<0||j<=i||j>=5)return 2;if(!seed){RSearch s(ORIGINAL,ids,i,j);s.run(sec,threads);return s.found?0:1;}mt19937 rng(seed);Perm pi{};iota(pi.begin(),pi.end(),0);shuffle(pi.begin()+1,pi.end(),rng);Key k{};do{for(auto&x:k)x=rng()%N;}while(equal(k.begin(),k.begin()+4,k.begin()+4));vector<string>p,c;for(auto&w:ORIGINAL){auto&v=by[w.size()];vector<double>weights;for(auto&x:v)weights.push_back(max(1,freq[x]));discrete_distribution<int>d(weights.begin(),weights.end());p.push_back(v[d(rng)]);c.push_back(rencode(p.back(),pi,k,rng()%Q));}RSearch s(c,ids,i,j);s.run(sec,threads);if(s.found){auto m=rmaps(s.answer,s.answerK);int h=0;for(int x:s.held)h+=decode(c[x],m).count(p[x]);cout<<"CONTROL action="<<rEqual(s.answer,s.answerK,pi,k)<<" heldtruth="<<h<<"/"<<s.held.size()<<endl;return rEqual(s.answer,s.answerK,pi,k)&&h==(int)s.held.size()?0:1;}return 1;}
